//! WPT `fetch/data-urls/resources/base64.json`: forgiving-base64 decode
//! cases, as a table of (input code points, expected bytes or failure).
//!
//! The file is a JSON array of `[input, output]` pairs, one per line, where
//! `output` is an array of byte values or `null` (failure). WPT runs each
//! through `fetch("data:;base64," + input)`, so the input first passes
//! through the URL parser and the data: URL processor before reaching
//! forgiving-base64 decode. The converter feeds the input to decode
//! directly; `check_direct` rejects any row where that could differ (see
//! there), so a new upstream row that needs the URL layer fails the
//! conversion instead of being silently misread.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["base64.json"];

struct Case {
    line: usize,
    input: Vec<u32>,
    /// `None`: decode must fail.
    expected: Option<Vec<u8>>,
}

/// Rows whose result could depend on the URL layer.
///
/// For `data:;base64,<input>`, the URL parser removes ASCII tab or newline
/// anywhere and C0 control or space at the start and end of the whole URL,
/// and percent-encodes other C0 controls, U+007F and non-ASCII; the data:
/// URL processor then percent-decodes the body and isomorphic-decodes it.
/// - Tab, LF, CR and space are ASCII whitespace, which decode step 1
///   removes anyway; a leading or trailing FF likewise.
/// - A percent-encoded code point comes back unchanged if it is ASCII; if
///   it is not, it comes back as one or more code points U+0080 to U+00FF.
///   Decode fails at step 4 on both the original and those (none of them
///   is in the alphabet, whitespace or "=").
/// - What does differ: "%" (percent-decoding changes the body), "#" (starts
///   a fragment, which the data: URL processor drops), and a non-whitespace
///   C0 control at the very end (stripped by the URL parser, but rejected
///   by decode). Those rows are refused.
fn check_direct(input: &[u32]) -> Result<(), String> {
    if let Some(c) = input
        .iter()
        .find(|&&c| c == u32::from('%') || c == u32::from('#'))
    {
        return Err(format!("contains U+{c:04X}, which the URL layer changes"));
    }
    let whitespace = [0x09, 0x0A, 0x0C, 0x0D, 0x20];
    if let Some(&last) = input.last()
        && last <= 0x20
        && !whitespace.contains(&last)
    {
        return Err(format!(
            "ends with U+{last:04X}, which the URL parser strips"
        ));
    }
    Ok(())
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let path = dir.join("base64.json");
    let text = std::fs::read_to_string(&path).map_err(|e| format!("base64.json: {e}"))?;
    let rows: Value = serde_json::from_str(&text).map_err(|e| format!("base64.json: {e}"))?;
    let rows = rows.as_array().ok_or("base64.json: not a JSON array")?;
    // One row per line: the line numbers of the lines that start a row.
    let lines: Vec<usize> = text
        .lines()
        .enumerate()
        .filter(|(_, l)| l.trim_start().starts_with('['))
        .map(|(i, _)| i.saturating_add(1))
        .filter(|&n| n > 1)
        .collect();
    if lines.len() != rows.len() {
        return Err(format!(
            "base64.json: {} rows but {} row lines; expected one row per line",
            rows.len(),
            lines.len()
        ));
    }
    let mut cases = Vec::new();
    for (row, &line) in rows.iter().zip(&lines) {
        let at = |e: String| format!("base64.json:{line}: {e}");
        let [input, output] = row.as_array().map(Vec::as_slice).unwrap_or_default() else {
            return Err(at("expected [input, output]".into()));
        };
        let input: Vec<u32> = input
            .as_str()
            .ok_or_else(|| at("input is not a string".into()))?
            .chars()
            .map(u32::from)
            .collect();
        check_direct(&input).map_err(at)?;
        let expected = match output {
            Value::Null => None,
            Value::Array(bytes) => Some(
                bytes
                    .iter()
                    .map(|b| {
                        b.as_u64()
                            .and_then(|b| u8::try_from(b).ok())
                            .ok_or_else(|| at(format!("not a byte: {b}")))
                    })
                    .collect::<Result<Vec<u8>, String>>()?,
            ),
            other => return Err(at(format!("output is neither null nor an array: {other}"))),
        };
        cases.push(Case {
            line,
            input,
            expected,
        });
    }
    render(&cases)
}

fn render(cases: &[Case]) -> Result<String, String> {
    let mut out = String::new();
    out.push_str("// @generated by `cargo xtask testdata` from tests/data/wpt-base64/.\n");
    out.push_str("// Do not edit: `cargo xtask verify` fails if this differs from what the\n");
    out.push_str("// converter (xtask/src/testdata/wpt_base64.rs) produces.\n");
    out.push_str("// Source, commit and license: tests/data/wpt-base64/SOURCE.md.\n");
    out.push_str("const WPT: &[Case] = &[\n");
    for c in cases {
        let input: Vec<String> = c.input.iter().map(|u| format!("0x{u:04X}")).collect();
        let expected = match &c.expected {
            None => "None".to_owned(),
            Some(v) => {
                let v: Vec<String> = v.iter().map(|b| format!("0x{b:02X}")).collect();
                format!("Some(&[{}])", v.join(", "))
            }
        };
        writeln!(
            out,
            "    Case {{ line: {}, input: &[{}], expected: {expected} }},",
            c.line,
            input.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::check_direct;

    #[test]
    fn url_layer_rows_are_refused() {
        assert!(check_direct(&[0x61, 0x62]).is_ok());
        assert!(check_direct(&[0x61, 0x0C]).is_ok());
        assert!(check_direct(&[0x00, 0x61]).is_ok());
        assert!(check_direct(&[0x61, 0x25, 0x62]).is_err());
        assert!(check_direct(&[0x61, 0x23]).is_err());
        assert!(check_direct(&[0x61, 0x0B]).is_err());
    }
}
